/// <summary>
/// TMSEngine move it in batch class
/// <c>METTMSEngineController</c> Run the TMSEngine in batch for the given transferId
/// </summary>
class METTMSEngineController extends SysOperationServiceController
{
}

Method.Source:
/// <summary>
/// TMSEngine move it in batch class
/// </summary>
/// <param name = "_transferId">transferId</param>
public static void runInBatch(InventTransferId _transferId)
{
    METTMSEngineController controller = new METTMSEngineController(
        classStr(METTMSEngineService),
        methodStr(METTMSEngineService, process),
        SysOperationExecutionMode::Asynchronous
    );

    METTMSEngineContract contract = controller.getDataContractObject() as METTMSEngineContract;
    contract.parmTransferId(_transferId);

    controller.parmShowDialog(false);
    controller.parmDialogCaption(strFmt("@MET:METTOCreated", _transferId));
    controller.startOperation();
}
